-- ==============================================================
-- BASE DE DATOS OFICIAL: SOPHOS CORE
-- Versión del esquema: 3.1 (Producción SENA)
-- 10 Estudiantes | 5 Materias | 600 Calificaciones P1, P2 y P3
-- ==============================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS `sophos_core` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci;
USE `sophos_core`;

DROP TABLE IF EXISTS `planes_suscripcion`;
CREATE TABLE `planes_suscripcion` (
  `id_suscripcion` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `precio` decimal(10,2) NOT NULL,
  `limite_usuarios` int(11) NOT NULL,
  PRIMARY KEY (`id_suscripcion`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `instituciones`;
CREATE TABLE `instituciones` (
  `id_institucion` char(36) NOT NULL DEFAULT uuid(),
  `nit` varchar(20) NOT NULL,
  `nombre_legal` varchar(200) NOT NULL,
  `dominio_personalizado` varchar(100) DEFAULT NULL,
  `subdomain` varchar(50) DEFAULT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `nomenclatura_cursos` varchar(50) DEFAULT NULL,
  `estado_suscripcion` enum('ACTIVO','INACTIVE','PRUEBA') NOT NULL DEFAULT 'PRUEBA',
  `id_suscripcion` int(10) unsigned DEFAULT NULL,
  `fecha_expiracion` datetime DEFAULT (current_timestamp() + interval 30 day),
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_institucion`),
  UNIQUE KEY `nit` (`nit`),
  KEY `fk_inst_plan` (`id_suscripcion`),
  CONSTRAINT `fk_inst_plan` FOREIGN KEY (`id_suscripcion`) REFERENCES `planes_suscripcion` (`id_suscripcion`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `usuarios`;
CREATE TABLE `usuarios` (
  `id_usuario` char(36) NOT NULL DEFAULT uuid(),
  `id_institucion` char(36) NOT NULL,
  `nombre_completo` varchar(200) NOT NULL,
  `email` varchar(150) NOT NULL,
  `password_hash` varchar(255) NOT NULL DEFAULT '$2y$10$moqsu2V8NmoU2/w7Tfdkqu1ip323iOFb2JFjVeoQWZveNsJSKi5QS',
  `rol` enum('SUPER_ADMIN','ADMIN','DOCENTE','ESTUDIANTE') NOT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `unique_email` (`email`),
  KEY `fk_usr_inst` (`id_institucion`),
  CONSTRAINT `fk_usr_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `cursos`;
CREATE TABLE `cursos` (
  `id_curso` char(36) NOT NULL DEFAULT uuid(),
  `id_institucion` char(36) NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `jornada` varchar(50) NOT NULL,
  PRIMARY KEY (`id_curso`),
  KEY `fk_cur_inst` (`id_institucion`),
  CONSTRAINT `fk_cur_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `estudiantes_matriculados`;
CREATE TABLE `estudiantes_matriculados` (
  `id_matricula` char(36) NOT NULL DEFAULT uuid(),
  `id_estudiante` char(36) NOT NULL,
  `id_curso` char(36) NOT NULL,
  `id_institucion` char(36) NOT NULL,
  `ano_lectivo` year(4) NOT NULL,
  PRIMARY KEY (`id_matricula`),
  KEY `fk_em_est` (`id_estudiante`),
  KEY `fk_em_cur` (`id_curso`),
  KEY `fk_em_inst` (`id_institucion`),
  CONSTRAINT `fk_em_cur` FOREIGN KEY (`id_curso`) REFERENCES `cursos` (`id_curso`) ON DELETE CASCADE,
  CONSTRAINT `fk_em_est` FOREIGN KEY (`id_estudiante`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE,
  CONSTRAINT `fk_em_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `materias`;
CREATE TABLE `materias` (
  `id_materia` char(36) NOT NULL DEFAULT uuid(),
  `id_institucion` char(36) NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `area` varchar(100) NOT NULL,
  PRIMARY KEY (`id_materia`),
  KEY `fk_mat_inst` (`id_institucion`),
  CONSTRAINT `fk_mat_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `periodos_academicos`;
CREATE TABLE `periodos_academicos` (
  `id_periodo` char(36) NOT NULL DEFAULT uuid(),
  `id_institucion` char(36) NOT NULL,
  `numero_periodo` tinyint(4) NOT NULL CHECK (`numero_periodo` between 1 and 4),
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 0,
  `fecha_creacion` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_periodo`),
  UNIQUE KEY `unique_periodo_inst` (`id_institucion`,`numero_periodo`),
  CONSTRAINT `fk_per_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `asignaciones_academicas`;
CREATE TABLE `asignaciones_academicas` (
  `id_asignacion` char(36) NOT NULL DEFAULT uuid(),
  `id_docente` char(36) NOT NULL,
  `id_curso` char(36) NOT NULL,
  `id_materia` char(36) NOT NULL,
  `id_institucion` char(36) NOT NULL,
  `ano_lectivo` year(4) NOT NULL,
  PRIMARY KEY (`id_asignacion`),
  KEY `fk_aa_doc` (`id_docente`),
  KEY `fk_aa_cur` (`id_curso`),
  KEY `fk_aa_mat` (`id_materia`),
  KEY `fk_aa_inst` (`id_institucion`),
  CONSTRAINT `fk_aa_cur` FOREIGN KEY (`id_curso`) REFERENCES `cursos` (`id_curso`) ON DELETE CASCADE,
  CONSTRAINT `fk_aa_doc` FOREIGN KEY (`id_docente`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE,
  CONSTRAINT `fk_aa_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE,
  CONSTRAINT `fk_aa_mat` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `evidencias`;
CREATE TABLE `evidencias` (
  `id_evidencia` char(36) NOT NULL DEFAULT uuid(),
  `id_institucion` char(36) NOT NULL,
  `id_materia` char(36) NOT NULL,
  `id_asignacion` char(36) NOT NULL,
  `numero_periodo` tinyint(4) NOT NULL,
  `nombre` varchar(200) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `ano_lectivo` year(4) NOT NULL,
  `orden` int(11) NOT NULL DEFAULT 1,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `fecha_creacion` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_evidencia`),
  KEY `fk_evi_inst` (`id_institucion`),
  KEY `fk_evi_mat` (`id_materia`),
  KEY `fk_evi_asig` (`id_asignacion`),
  CONSTRAINT `fk_evi_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE,
  CONSTRAINT `fk_evi_mat` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `calificaciones`;
CREATE TABLE `calificaciones` (
  `id_calificacion` char(36) NOT NULL DEFAULT uuid(),
  `id_matricula` char(36) NOT NULL,
  `id_asignacion` char(36) NOT NULL,
  `id_periodo` char(36) DEFAULT NULL,
  `id_evidencia` char(36) DEFAULT NULL,
  `id_institucion` char(36) NOT NULL,
  `nota` decimal(3,2) NOT NULL CHECK (`nota` between 0.00 and 5.00),
  `periodo` tinyint(4) NOT NULL,
  `actividad` varchar(150) NOT NULL DEFAULT 'General',
  `comentario_docente` text DEFAULT NULL,
  `comentario_ia` text DEFAULT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_calificacion`),
  KEY `fk_cal_mat` (`id_matricula`),
  KEY `fk_cal_asig` (`id_asignacion`),
  KEY `fk_cal_per` (`id_periodo`),
  KEY `fk_cal_evi` (`id_evidencia`),
  KEY `fk_cal_inst` (`id_institucion`),
  CONSTRAINT `fk_cal_asig` FOREIGN KEY (`id_asignacion`) REFERENCES `asignaciones_academicas` (`id_asignacion`) ON DELETE CASCADE,
  CONSTRAINT `fk_cal_evi` FOREIGN KEY (`id_evidencia`) REFERENCES `evidencias` (`id_evidencia`) ON DELETE SET NULL,
  CONSTRAINT `fk_cal_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE,
  CONSTRAINT `fk_cal_mat` FOREIGN KEY (`id_matricula`) REFERENCES `estudiantes_matriculados` (`id_matricula`) ON DELETE CASCADE,
  CONSTRAINT `fk_cal_per` FOREIGN KEY (`id_periodo`) REFERENCES `periodos_academicos` (`id_periodo`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `boletines_historicos`;
CREATE TABLE `boletines_historicos` (
  `id_boletin` char(36) NOT NULL DEFAULT uuid(),
  `id_matricula` char(36) NOT NULL,
  `id_periodo` char(36) NOT NULL,
  `id_institucion` char(36) NOT NULL,
  `promedio_general` decimal(4,2) NOT NULL,
  `datos_materias` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`datos_materias`)),
  `observacion_director` text DEFAULT NULL,
  `fecha_cierre` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_boletin`),
  UNIQUE KEY `unique_boletin` (`id_matricula`,`id_periodo`),
  KEY `fk_bol_per` (`id_periodo`),
  KEY `fk_bol_inst` (`id_institucion`),
  CONSTRAINT `fk_bol_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE,
  CONSTRAINT `fk_bol_mat` FOREIGN KEY (`id_matricula`) REFERENCES `estudiantes_matriculados` (`id_matricula`) ON DELETE CASCADE,
  CONSTRAINT `fk_bol_per` FOREIGN KEY (`id_periodo`) REFERENCES `periodos_academicos` (`id_periodo`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `asistencias`;
CREATE TABLE `asistencias` (
  `id_asistencia` char(36) NOT NULL DEFAULT uuid(),
  `id_matricula` char(36) NOT NULL,
  `id_asignacion` char(36) NOT NULL,
  `id_institucion` char(36) NOT NULL,
  `fecha` date NOT NULL DEFAULT curdate(),
  `estado` enum('FALTA_JUSTIFICADA','FALTA_INJUSTIFICADA') NOT NULL,
  `observacion` text DEFAULT NULL,
  PRIMARY KEY (`id_asistencia`),
  KEY `fk_asi_mat` (`id_matricula`),
  KEY `fk_asi_asig` (`id_asignacion`),
  KEY `fk_asi_inst` (`id_institucion`),
  CONSTRAINT `fk_asi_asig` FOREIGN KEY (`id_asignacion`) REFERENCES `asignaciones_academicas` (`id_asignacion`) ON DELETE CASCADE,
  CONSTRAINT `fk_asi_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE,
  CONSTRAINT `fk_asi_mat` FOREIGN KEY (`id_matricula`) REFERENCES `estudiantes_matriculados` (`id_matricula`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


DROP TABLE IF EXISTS `observador_digital`;
CREATE TABLE `observador_digital` (
  `id_observador` char(36) NOT NULL DEFAULT uuid(),
  `id_estudiante` char(36) NOT NULL,
  `id_docente` char(36) NOT NULL,
  `id_institucion` char(36) NOT NULL,
  `tipo_nota` enum('PEDAGOGICA','DISCIPLINARIA','LOGRO_DESTACADO') NOT NULL,
  `observacion_informal` text NOT NULL,
  `observacion_formal_ia` text DEFAULT NULL,
  `firmado` tinyint(1) NOT NULL DEFAULT 0,
  `firmado_por` char(36) DEFAULT NULL,
  `fecha_firma` datetime DEFAULT NULL,
  `fecha_registro` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id_observador`),
  KEY `fk_obs_est` (`id_estudiante`),
  KEY `fk_obs_doc` (`id_docente`),
  KEY `fk_obs_inst` (`id_institucion`),
  KEY `fk_obs_firma` (`firmado_por`),
  CONSTRAINT `fk_obs_doc` FOREIGN KEY (`id_docente`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE,
  CONSTRAINT `fk_obs_est` FOREIGN KEY (`id_estudiante`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE,
  CONSTRAINT `fk_obs_firma` FOREIGN KEY (`firmado_por`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL,
  CONSTRAINT `fk_obs_inst` FOREIGN KEY (`id_institucion`) REFERENCES `instituciones` (`id_institucion`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;


SET FOREIGN_KEY_CHECKS = 1;