INSERT INTO `observador_digital` (`id_observador`, `id_estudiante`, `id_docente`, `id_institucion`, `tipo_nota`, `observacion_informal`, `observacion_formal_ia`, `firmado`, `firmado_por`, `fecha_firma`, `fecha_registro`) VALUES
('obs00001-0000-0000-0000-000000000001', 'b0000001-0000-0000-0000-000000000001', 'b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'LOGRO_DESTACADO', 'Alex alcanzó el mayor promedio del grupo en el Taller 2 de optimización.', 'Se exalta el compromiso académico y la capacidad analítica sobresaliente del estudiante Alex Johnson en la resolución de problemas complejos de optimización matemática.', '1', 'b0000001-0000-0000-0000-000000000002', '2026-09-12 10:00:00', '2026-09-12 09:45:00'),
('obs00001-0000-0000-0000-000000000002', 'b0000001-0000-0000-0000-000000000008', 'b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'DISCIPLINARIA', 'Isabella faltó injustificadamente tres veces en octubre.', 'Se registra inasistencia reiterada sin justificación durante el Tercer Período. Se requiere comunicación formal con el núcleo familiar para restablecer la asistencia regular.', '1', 'b0000001-0000-0000-0000-000000000002', '2026-10-11 11:00:00', '2026-10-11 10:30:00'),
('obs00001-0000-0000-0000-000000000003', 'b0000001-0000-0000-0000-000000000010', 'b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'PEDAGOGICA', 'Valentina muestra dificultades persistentes en algebra y cálculo. Se recomendó tutoría IA.', 'El desempeño académico de Valentina Herrera presenta déficit conceptual acumulado en matemáticas. Se establece acuerdo de acompañamiento mediante la plataforma de tutoría inteligente SophosBot.', '1', 'b0000001-0000-0000-0000-000000000002', '2026-09-25 11:00:00', '2026-09-25 10:30:00'),
('obs00001-0000-0000-0000-000000000004', 'b0000001-0000-0000-0000-000000000004', 'b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'LOGRO_DESTACADO', 'Sofía obtuvo la nota más alta del examen semestral de Matemáticas en 10°A.', 'Se destaca a la estudiante Sofía Gómez por su rendimiento excepcional y liderazgo académico en el grado 10°A. Su promedio general supera consistentemente el 4.5.', '1', 'b0000001-0000-0000-0000-000000000002', '2026-07-01 10:00:00', '2026-06-28 15:00:00'),
('obs00001-0000-0000-0000-000000000005', 'b0000001-0000-0000-0000-000000000014', 'b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'PEDAGOGICA', 'Lucas entregó el proyecto de matemáticas incompleto. Segunda vez que ocurre en P3.', 'Se registra incumplimiento reiterado en la entrega de evidencias académicas por parte del estudiante Lucas Sebastián Ramírez. Se recomienda intervención coordinada con el director de grupo.', '1', 'b0000001-0000-0000-0000-000000000002', '2026-10-13 09:00:00', '2026-10-13 08:30:00');
